-- ============================================================================
-- v1361: Sample data for the Technology Workstreams form
-- ============================================================================
-- Fills the fields added in v1358 on the ten Northbridge workstreams from v1355.
-- Values come from the matching Delivery Overview sample for the same slice.
-- Existing keys win, so a value already entered on a record is left as it is.
-- Cybersecurity moves from Not Started to On Hold only while it is still the
-- untouched sample status. Linked registers stay empty: the Related tab reads them.
-- Idempotent. Prerequisite: v1355, v1358.
-- ============================================================================

UPDATE public.local_register_records AS r
SET field_values = v.seed::jsonb || COALESCE(r.field_values, '{}'::jsonb),
    status = CASE
      WHEN r.status = v.original_status AND v.new_status IS DISTINCT FROM v.original_status THEN v.new_status
      ELSE r.status
    END,
    updated_at = NOW()
